"""Canonical language machine for the eMicro policy language.

A policy denotes a set of finite service sequences.  This module turns parsed
rules into a hash-consed language expression, enumerates its Brzozowski
derivatives into a deterministic complete automaton, minimises it by partition
refinement and exports the canonical live-state table demanded by the control
plane: the minimal deterministic complete machine with its dead residual
removed (START is always retained) and residuals numbered by breadth-first
discovery, columns in increasing service-label order, DENY for every dead
transition.

The algebra is intentionally structural and total: every constructor keeps a
canonical form so that equal expressions are one object whenever the shapes
agree, which bounds the derivative closure of every expressible policy.
"""

__all__ = ['PolicyError', 'language', 'automaton', 'minimize', 'canonical',
           'E_EMPTY', 'E_ALL', 'DENY']

DENY = 4294967295
MAX_STATES = 120000  # an expressible policy never needs more residuals

_EMPTY = 0
_ALL = 1
_WORD = 2   # {path}                    (match)
_PRE = 3     # words starting with path (startswith)
_SUF = 4     # words ending with path   (endswith)
_SUB = 5     # words containing path    (contains)
_UNION = 6
_INTER = 7
_COMPL = 8

E_EMPTY = (_EMPTY,)
E_ALL = (_ALL,)


class PolicyError(Exception):
    """Compilable-language failure: unregistered service or oversized image."""


# ------------------------------------------------------------ constructors --
def _pre(path):
    return (_PRE, path) if path else E_ALL


def mk_word(path):
    return (_WORD, path)


def mk_union(members):
    """Canonical union: idempotent, flattening, absorbing constants."""
    out = set()
    for m in members:
        tag = m[0]
        if tag == _ALL:
            return E_ALL
        if tag == _EMPTY:
            continue
        if tag == _UNION:
            out.update(m[1])
        else:
            out.add(m)
    if not out:
        return E_EMPTY
    if len(out) == 1:
        return next(iter(out))
    for m in out:
        if m[0] == _COMPL and m[1] in out:
            return E_ALL
    return (_UNION, frozenset(out))


def mk_inter(members):
    """Canonical intersection: idempotent, flattening, absorbing constants."""
    out = set()
    for m in members:
        tag = m[0]
        if tag == _EMPTY:
            return E_EMPTY
        if tag == _ALL:
            continue
        if tag == _INTER:
            out.update(m[1])
        else:
            out.add(m)
    if not out:
        return E_ALL
    if len(out) == 1:
        return next(iter(out))
    for m in out:
        if m[0] == _COMPL and m[1] in out:
            return E_EMPTY
    return (_INTER, frozenset(out))


def mk_compl(expr):
    tag = expr[0]
    if tag == _COMPL:
        return expr[1]
    if tag == _EMPTY:
        return E_ALL
    if tag == _ALL:
        return E_EMPTY
    return (_COMPL, expr)


# ----------------------------------------------------------------- language --
def _atom(node, columns):
    kind, names = node
    try:
        path = tuple(columns[name] for name in names)
    except KeyError:
        raise PolicyError('unregistered service in path') from None
    if kind == 'match':
        return (_WORD, path)
    if kind == 'startswith':
        return _pre(path)
    if kind == 'endswith':
        return (_SUF, path) if path else E_ALL
    return (_SUB, path) if path else E_ALL


def _expr(node, columns):
    tag = node[0]
    if tag == 'and':
        return mk_inter((_expr(node[1], columns), _expr(node[2], columns)))
    if tag == 'or':
        return mk_union((_expr(node[1], columns), _expr(node[2], columns)))
    if tag == 'not':
        return mk_compl(_expr(node[1], columns))
    return _atom(node, columns)


def language(rules, columns):
    """Build the canonical expression of a parsed rule list.

    A sequence is allowed iff at least one allow rule matches and no drop rule
    matches; no allow rules means the empty language.
    """
    allows = []
    drops = []
    for predicate, is_allow in rules:
        expr = _expr(predicate, columns)
        (allows if is_allow else drops).append(expr)
    if not allows:
        return E_EMPTY
    allowed = mk_union(allows)
    if not drops:
        return allowed
    return mk_inter((allowed, mk_compl(mk_union(drops))))


# ------------------------------------------------------------- derivatives --
def nullable(expr):
    """Whether the empty sequence belongs to the expression's language."""
    while True:
        tag = expr[0]
        if tag == _ALL:
            return True
        if tag == _EMPTY:
            return False
        if tag == _WORD:
            return not expr[1]
        if tag == _PRE or tag == _SUF or tag == _SUB:
            return False
        if tag == _UNION:
            for member in expr[1]:
                if nullable(member):
                    return True
            return False
        if tag == _INTER:
            for member in expr[1]:
                if not nullable(member):
                    return False
            return True
        expr = expr[1]
        # complement: recurse once without another frame
        return not nullable(expr)


def deriv(expr, column):
    """Right-derivative of ``expr`` by the service in ``column``."""
    tag = expr[0]
    if tag == _WORD:
        path = expr[1]
        if path and path[0] == column:
            return (_WORD, path[1:])
        return E_EMPTY
    if tag == _PRE:
        path = expr[1]
        if path and path[0] == column:
            return _pre(path[1:])
        return E_EMPTY
    if tag == _SUF:
        path = expr[1]
        if path[0] == column:
            return mk_union((expr, (_WORD, path[1:])))
        return expr
    if tag == _SUB:
        path = expr[1]
        if path[0] == column:
            return mk_union((expr, _pre(path[1:])))
        return expr
    if tag == _UNION:
        return mk_union([deriv(member, column) for member in expr[1]])
    if tag == _INTER:
        return mk_inter([deriv(member, column) for member in expr[1]])
    if tag == _COMPL:
        return mk_compl(deriv(expr[1], column))
    return expr  # E_EMPTY / E_ALL are invariant


def automaton(expr, columns):
    """Derivative closure: reachable complete deterministic automaton.

    Returns ``(transitions, accept)``; state 0 is the start residual and
    ``transitions[s][c]`` is the derivative by column ``c``.
    """
    ids = {expr: 0}
    states = [expr]
    transitions = []
    index = 0
    while index < len(states):
        current = states[index]
        index += 1
        row = []
        for column in range(columns):
            nxt = deriv(current, column)
            target = ids.get(nxt)
            if target is None:
                target = len(states)
                if target >= MAX_STATES:
                    raise PolicyError('derivative closure too large')
                ids[nxt] = target
                states.append(nxt)
            row.append(target)
        transitions.append(row)
    accept = [nullable(state) for state in states]
    return transitions, accept


# ------------------------------------------------------------ minimisation --
def minimize(transitions, accept):
    """Moore partition refinement; returns the stable class of every state."""
    count = len(transitions)
    if count == 1:
        return [0]
    classes = [1 if flag else 0 for flag in accept]
    distinct = len(set(classes))
    while True:
        signatures = {}
        cls_get = classes.__getitem__
        new = [0] * count
        for state in range(count):
            sig = (classes[state],) + tuple(map(cls_get, transitions[state]))
            label = signatures.get(sig)
            if label is None:
                label = len(signatures)
                signatures[sig] = label
            new[state] = label
        if len(signatures) == distinct:
            # Moore only ever splits, so an unchanged class count is a fixpoint.
            return new
        classes = new
        distinct = len(signatures)


def canonical(transitions, accept, classes, columns):
    """Minimal complete machine minus its dead residual, BFS-numbered.

    Returns ``(accept_flags, rows)``.  Row 0 is START; DENY marks transitions
    into the removed dead residual, and rows are numbered by breadth-first
    discovery from START considering columns in increasing service-label
    order and ignoring DENY.
    """
    start_class = classes[0]
    nclasses = 1 + max(classes)
    ctrans = [None] * nclasses
    caccept = [False] * nclasses
    for state in range(len(transitions)):
        cls = classes[state]
        if ctrans[cls] is None:
            ctrans[cls] = [classes[target] for target in transitions[state]]
            caccept[cls] = bool(accept[state])
    dead = None
    for cls in range(nclasses):
        if not caccept[cls] and all(target == cls for target in ctrans[cls]):
            dead = cls
            break
    order = [start_class]
    numbers = {start_class: 0}
    head = 0
    while head < len(order):
        cls = order[head]
        head += 1
        for target in ctrans[cls]:
            if target != dead:
                if target not in numbers:
                    numbers[target] = len(order)
                    order.append(target)
    rows = []
    flags = []
    for cls in order:
        row = ctrans[cls]
        rows.append([DENY if target == dead else numbers[target]
                     for target in row])
        flags.append(caccept[cls])
    return flags, rows
