"""Brute-force cross-check of the canonical image against direct evaluation."""
import sys, itertools
sys.path.insert(0, '/workspace/project')
from syntax import parse, PolicyError
import compiler.compiler as C


def eval_pred(node, word):
    tag = node[0]
    if tag == 'and':
        return eval_pred(node[1], word) and eval_pred(node[2], word)
    if tag == 'or':
        return eval_pred(node[1], word) or eval_pred(node[2], word)
    if tag == 'not':
        return not eval_pred(node[1], word)
    path = node[1]
    if tag == 'match':
        return tuple(path) == word
    if tag == 'startswith':
        return tuple(path) == word[:len(path)]
    if tag == 'endswith':
        return tuple(path) == word[-len(path):] if path else True
    if tag == 'contains':
        n, m = len(word), len(path)
        if not path:
            return True
        return any(tuple(word[i:i+m]) == tuple(path) for i in range(n - m + 1))
    raise AssertionError(tag)


def lang_of(rules, word):
    allowed = [r for r in rules if r[1]]
    dropped = [r for r in rules if not r[1]]
    if not allowed:
        return False
    if not any(eval_pred(p, word) for p, _ in allowed):
        return False
    if any(eval_pred(p, word) for p, _ in dropped):
        return False
    return True


def image(text, cols):
    rules, a, p = parse(text)
    expr = C.language(rules, cols)
    t, acc = C.automaton(expr, len(cols))
    cls = C.minimize(t, acc)
    return C.canonical(t, acc, cls, len(cols))


def walk(flags, rows, word, k):
    """Return the state after reading word from START (or DENY)."""
    s = 0
    for c in word:
        if s == C.DENY:
            return C.DENY
        s = rows[s][c]
    return s


def check(text, names, limit=6, extra=None):
    """Verify language, minimality and BFS numbering against brute force."""
    k = len(names)
    cols = {n: i for i, n in enumerate(names)}
    flags, rows = image(text, cols)
    # 1. language agreement up to `limit`
    for n in range(limit + 1):
        for word in itertools.product(range(k), repeat=n):
            st = walk(flags, rows, word, k)
            got = (st != C.DENY and flags[st])
            rules, _, _ = parse(text)
            want = lang_of(rules, word)
            if got != want:
                return 'language mismatch at %r: got %s want %s' % (word, got, want)
    # 2. dead removal: no non-DENY target may be a dead state (a state that
    #    cannot reach acceptance)
    live = set()
    n = len(rows)
    # states that reach acceptance
    reach = set(i for i in range(n) if flags[i])
    changed = True
    while changed:
        changed = False
        for i in range(n):
            if i in reach:
                continue
            for t in rows[i]:
                if t != C.DENY and t in reach:
                    reach.add(i); changed = True; break
    if reach != set(range(n)):
        return 'retained dead state: %s' % (set(range(n)) - reach)
    # 3. minimality: no two distinct states (incl. DENY) equivalent up to depth D
    D = extra if extra else 6
    sig = {}
    for i in list(range(n)) + [C.DENY]:
        acc_i = (i != C.DENY and flags[i])
        sigs = []
        for m in range(D + 1):
            for word in itertools.product(range(k), repeat=m):
                st = walk(flags, rows, word, k) if i != C.DENY else C.DENY
                # advance from i
                st = i
                ok = True
                for c in word:
                    if st == C.DENY:
                        break
                    st = rows[st][c]
                else:
                    pass
                if st == C.DENY:
                    val = False
                else:
                    val = flags[st]
                sigs.append(val)
        sig[i] = (acc_i, tuple(sigs))
    seen = {}
    for i, s in sig.items():
        if s in seen:
            return 'states %s and %s look equivalent' % (seen[s], i)
        seen[s] = i
    # 4. BFS numbering
    order = [0]
    seen = {0}
    head = 0
    while head < len(order):
        s = order[head]; head += 1
        for c in range(k):
            t = rows[s][c]
            if t != C.DENY and t not in seen:
                seen.add(t); order.append(t)
    if order != list(range(n)):
        return 'BFS order mismatch: %s' % order
    return None


if __name__ == '__main__':
    names = ['A', 'B']
    cases = [
        '', 'match(A) allow;', 'match(A) allow; match(A) drop;',
        'startswith(A) allow;', 'endswith(A) allow;', 'contains(A,B) allow;',
        'not(contains(A)) allow;', 'match(A,B) allow; match(B,A) allow;',
        '((match(A) or match(B)) and not(match(A))) allow;',
        'contains(A) drop; startswith(B) allow;',
        'match() allow;', 'startswith() allow;', 'contains() drop; match(A) allow;',
        'endswith(A,B) allow; not(endswith(B,A)) allow;',
        '(contains(A) and contains(B)) or match(A,A) allow;',
        'not(startswith(A)) and not(endswith(B)) allow; contains(B) drop;',
        'match(A) drop; match(B) drop; startswith(A,A) allow;',
        'endswith() allow; match(A,B,A) drop;',
        'not(match()) allow;', 'not(match(A)) allow;',
        'contains(A) and not(contains(A,B)) allow;',
    ]
    bad = 0
    for text in cases:
        err = check(text, names)
        if err:
            bad += 1
            print('FAIL %r: %s' % (text, err))
    print('checked', len(cases), 'policies,', bad, 'failures')
