"""Randomised cross-check of the canonical image against brute-force language."""
import sys, random, itertools
sys.path.insert(0, '/workspace/project')
sys.path.insert(0, '/workspace/tests')
from syntax import parse, PolicyError, MAX_DISTINCT_NONMATCH, MAX_NONMATCH_PATH
import compiler.compiler as C
from brute import check, image

KINDS = ('match', 'startswith', 'endswith', 'contains')


def rand_path(rng, names, maxlen):
    n = rng.randint(0, min(maxlen, len(names)))
    return tuple(rng.choice(names) for _ in range(n))


def rand_pred(rng, names, depth, nonmatch):
    if depth <= 1 or rng.random() < 0.4:
        kind = rng.choice(KINDS)
        limit = MAX_NONMATCH_PATH if kind != 'match' else 16
        path = rand_path(rng, names, min(limit, 3))
        if kind != 'match':
            key = (kind, path)
            if key not in nonmatch:
                if len(nonmatch) >= MAX_DISTINCT_NONMATCH:
                    # reuse an existing non-match atom
                    kind, path = rng.choice(list(nonmatch))
                else:
                    nonmatch.add(key)
        return (kind, path)
    which = rng.random()
    if which < 0.3:
        return ('not', rand_pred(rng, names, depth - 1, nonmatch))
    left = rand_pred(rng, names, depth - 1, nonmatch)
    right = rand_pred(rng, names, depth - 1, nonmatch)
    return (rng.choice(('and', 'or')), left, right)


def gen(rng, names):
    nonmatch = set()
    rules = []
    for _ in range(rng.randint(0, 4)):
        pred = rand_pred(rng, names, rng.randint(1, 4), nonmatch)
        rules.append((pred, rng.random() < 0.6))
    # render
    def show(p):
        if p[0] in ('and', 'or'):
            return '(%s %s %s)' % (show(p[1]), p[0], show(p[2]))
        if p[0] == 'not':
            return 'not(%s)' % show(p[1])
        return '%s(%s)' % (p[0], ','.join(p[1]))
    return ' '.join('%s %s;' % (show(p), 'allow' if a else 'drop') for p, a in rules)


def main(seed, count, services=2, limit=6):
    rng = random.Random(seed)
    names = [chr(65 + i) for i in range(services)]
    bad = 0
    for i in range(count):
        text = gen(rng, names)
        try:
            parse(text)
        except PolicyError:
            continue
        err = check(text, names, limit=limit, depth=limit)
        if err:
            bad += 1
            print('FAIL %r: %s' % (text, err))
            if bad > 4:
                break
    print('fuzz seed=%d count=%d services=%d failures=%d' % (seed, count, services, bad))


if __name__ == '__main__':
    main(1, 400, 2, 6)
    main(2, 300, 3, 5)
    main(3, 300, 2, 7)
    main(4, 200, 4, 4)
