"""Independent slow reference model of the replay contract."""
import sys
sys.path.insert(0, '/workspace/project')
import struct
from syntax import parse
from ebpf.create_dfa import create

DENY = 4294967295
_WIRE = struct.Struct('>4sIIIII')
REJ = {'error': 'rejected'}


class Ref(object):
    def __init__(self, services, limits):
        self.label = dict((s['name'], s['label']) for s in services)
        self.order = sorted(self.label, key=lambda n: self.label[n])
        self.lim = limits
        self.img = {}       # epoch -> (accept, rows, cells)
        self.refs = {}
        self.active = None
        self.stage_mark = 0
        self.units = {}     # (ns,pid) -> dict(gen=, service=, ctx={rid:(epoch,state)}, mark=)
        self.gmark = {}
        self.conns = {}     # id -> dict(gen=, mark=, pk={stream: [...]})
        self.cmark = {}
        self.files = {}     # id -> dict(gen=, epoch=, state=)
        self.fmark = {}
        self.cache = {}

    # ---- helpers
    def unit(self, ns, pid, gen):
        u = self.units.get((ns, pid))
        if u is None or u['gen'] != gen:
            return None
        return u

    def ncontexts(self):
        return sum(len(u['ctx']) for u in self.units.values())

    def npackets(self):
        return sum(len(c['pk']) for c in self.conns.values())

    def compile(self, text):
        if text in self.cache:
            return self.cache[text]
        try:
            rules, _, _ = parse(text)
            cols = dict((n, i) for i, n in enumerate(self.order))
            table = create(rules, cols, len(self.order))
        except Exception:
            table = None
        self.cache[text] = table
        return table

    def advance(self, epoch, state, service):
        if state == DENY:
            return DENY
        return self.img[epoch][1][state][self.order.index(service)]

    def wire(self, epoch, state, dest, stream, gen):
        return _WIRE.pack(b'EMC4', epoch, state, self.label[dest], stream, gen).hex()

    # ---- operations
    def stage(self, e):
        ep = e['epoch']
        if ep <= self.stage_mark:
            return REJ
        if len(self.img) >= self.lim['images']:
            return REJ
        t = self.compile(e['policy'])
        if t is None:
            return REJ
        cells = t[2]
        if sum(self.img[x][2] for x in self.img) + cells > self.lim['cells']:
            return REJ
        self.img[ep] = t
        self.refs[ep] = 0
        self.stage_mark = ep
        return {'ok': True, 'epoch': ep, 'image': {'accept': t[0], 'rows': t[1]}}

    def commit(self, e):
        if e['epoch'] not in self.img:
            return REJ
        self.active = e['epoch']
        return {'ok': True}

    def retire(self, e):
        ep = e['epoch']
        if ep not in self.img or ep == self.active or self.refs.get(ep, 0) != 0:
            return REJ
        del self.img[ep]
        del self.refs[ep]
        return {'ok': True}

    def spawn(self, e):
        ns, pid, gen = e['unit']
        if (ns, pid) in self.units:
            return REJ
        if gen <= self.gmark.get((ns, pid), 0):
            return REJ
        if e['service'] not in self.label:
            return REJ
        if len(self.units) >= self.lim['units']:
            return REJ
        self.units[(ns, pid)] = dict(gen=gen, service=e['service'], ctx={}, mark=0)
        self.gmark[(ns, pid)] = gen
        return {'ok': True}

    def clone(self, e):
        p = self.unit(*e['parent'])
        if p is None:
            return REJ
        ns, pid, gen = e['child']
        if (ns, pid) in self.units or gen <= self.gmark.get((ns, pid), 0):
            return REJ
        if len(self.units) >= self.lim['units']:
            return REJ
        if self.ncontexts() + len(p['ctx']) > self.lim['contexts']:
            return REJ
        child = dict(gen=gen, service=p['service'], ctx=dict(p['ctx']), mark=p['mark'])
        for ep, st in child['ctx'].values():
            self.refs[ep] += 1
        self.units[(ns, pid)] = child
        self.gmark[(ns, pid)] = gen
        return {'ok': True}

    def exit(self, e):
        u = self.unit(*e['unit'])
        if u is None:
            return REJ
        for ep, st in u['ctx'].values():
            self.refs[ep] -= 1
        del self.units[(e['unit'][0], e['unit'][1])]
        return {'ok': True}

    def begin(self, e):
        u = self.unit(*e['unit'])
        if u is None or self.active is None:
            return REJ
        if e['rid'] <= u['mark']:
            return REJ
        if self.ncontexts() >= self.lim['contexts']:
            return REJ
        ep = self.active
        st = self.advance(ep, 0, u['service'])
        u['ctx'][e['rid']] = (ep, st)
        u['mark'] = e['rid']
        self.refs[ep] += 1
        return {'ok': True, 'epoch': ep, 'state': st}

    def finish(self, e):
        u = self.unit(*e['unit'])
        if u is None or e['rid'] not in u['ctx']:
            return REJ
        ep, st = u['ctx'].pop(e['rid'])
        self.refs[ep] -= 1
        allow = bool(self.img[ep][0][st]) if st != DENY else False
        return {'ok': True, 'allow': allow}

    def open(self, e):
        cid, gen = e['connection']
        if cid in self.conns or gen <= self.cmark.get(cid, 0):
            return REJ
        if len(self.conns) >= self.lim['connections']:
            return REJ
        self.conns[cid] = dict(gen=gen, mark=0, pk={})
        self.cmark[cid] = gen
        return {'ok': True}

    def send(self, e):
        u = self.unit(*e['unit'])
        if u is None or e['rid'] not in u['ctx']:
            return REJ
        cid, gen = e['connection']
        c = self.conns.get(cid)
        if c is None or c['gen'] != gen:
            return REJ
        if e['stream'] <= c['mark']:
            return REJ
        if e['destination'] not in self.label:
            return REJ
        if self.npackets() >= self.lim['packets']:
            return REJ
        ep, st = u['ctx'][e['rid']]
        c['pk'][e['stream']] = dict(ep=ep, st=st, dest=e['destination'],
                                     receipt=None, gen=gen,
                                     wire=self.wire(ep, st, e['destination'], e['stream'], gen))
        c['mark'] = e['stream']
        self.refs[ep] += 1
        return {'ok': True, 'wire': c['pk'][e['stream']]['wire']}

    def recv(self, e):
        cid, gen = e['connection']
        c = self.conns.get(cid)
        if c is None or c['gen'] != gen or e['stream'] not in c['pk']:
            return REJ
        p = c['pk'][e['stream']]
        u = self.unit(*e['unit'])
        if u is None or u['service'] != p['dest']:
            return REJ
        w = e['wire']
        if w is not None and (len(w) != 48 or w.lower() != p['wire']):
            return REJ
        ns, pid, ugen = e['unit']
        if p['receipt'] is None:
            if e['rid'] <= u['mark']:
                return REJ
            if self.ncontexts() >= self.lim['contexts']:
                return REJ
            st = self.advance(p['ep'], p['st'], u['service'])
            u['ctx'][e['rid']] = (p['ep'], st)
            u['mark'] = e['rid']
            self.refs[p['ep']] += 1
            p['receipt'] = ((ns, pid, ugen), e['rid'])
            return {'ok': True, 'epoch': p['ep'], 'state': st}
        if p['receipt'] != ((ns, pid, ugen), e['rid']):
            return REJ
        if e['rid'] not in u['ctx']:
            return REJ
        ep, st = u['ctx'][e['rid']]
        return {'ok': True, 'epoch': ep, 'state': st}

    def close(self, e):
        cid, gen = e['connection']
        c = self.conns.get(cid)
        if c is None or c['gen'] != gen:
            return REJ
        for p in c['pk'].values():
            self.refs[p['ep']] -= 1
        del self.conns[cid]
        return {'ok': True}

    def store(self, e):
        u = self.unit(*e['unit'])
        if u is None or e['rid'] not in u['ctx']:
            return REJ
        fid, gen = e['file']
        f = self.files.get(fid)
        ep, st = u['ctx'][e['rid']]
        if f is None:
            if gen <= self.fmark.get(fid, 0):
                return REJ
            if len(self.files) >= self.lim['files']:
                return REJ
            self.files[fid] = dict(gen=gen, epoch=ep, state=st)
            self.fmark[fid] = gen
            self.refs[ep] += 1
        else:
            if f['gen'] != gen:
                return REJ
            self.refs[f['epoch']] -= 1
            f['epoch'] = ep
            f['state'] = st
            self.refs[ep] += 1
        return {'ok': True}

    def load(self, e):
        fid, gen = e['file']
        f = self.files.get(fid)
        if f is None or f['gen'] != gen:
            return REJ
        u = self.unit(*e['unit'])
        if u is None:
            return REJ
        if e['rid'] <= u['mark']:
            return REJ
        if self.ncontexts() >= self.lim['contexts']:
            return REJ
        st = self.advance(f['epoch'], f['state'], u['service'])
        u['ctx'][e['rid']] = (f['epoch'], st)
        u['mark'] = e['rid']
        self.refs[f['epoch']] += 1
        return {'ok': True, 'epoch': f['epoch'], 'state': st}

    def unlink(self, e):
        fid, gen = e['file']
        f = self.files.get(fid)
        if f is None or f['gen'] != gen:
            return REJ
        self.refs[f['epoch']] -= 1
        del self.files[fid]
        return {'ok': True}

    def inspect(self, e):
        images = [[ep, len(self.img[ep][1]), self.img[ep][2], self.refs[ep]]
                  for ep in sorted(self.img)]
        return {'ok': True, 'active': self.active, 'images': images,
                'units': len(self.units), 'contexts': self.ncontexts(),
